const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');require('../scripts/register.cjs');
const root=path.resolve(__dirname,'..');const {projects,articles,sources,evidence,searchEntries,siteRoutes}=require('../lib/content.ts');const {searchDocuments,matchProject}=require('../lib/search.ts');const {View,routeTitle}=require('../components/views.tsx');const {render}=require('../scripts/serialize.cjs');
test('implementation includes typed content',()=>assert.ok(fs.existsSync(path.join(root,'lib/content.ts'))));
test('all route identifiers are unique and local',()=>{assert.equal(new Set(siteRoutes).size,siteRoutes.length);assert.ok(siteRoutes.every(p=>p.startsWith('/')&&p.endsWith('/')))});
test('all sources resolve to declared HTTPS references',()=>{for(const p of projects)assert.ok(sources[p.source]);for(const a of articles)for(const id of a.sources)assert.ok(sources[id]);for(const e of evidence)assert.ok(sources[e.source]);assert.ok(Object.values(sources).every(s=>s.url.startsWith('https://github.com/')))});
test('articles contain substantial distinct content and stable heading IDs',()=>{for(const a of articles){assert.ok(a.sections.length>=3);assert.ok(a.sections.flatMap(s=>s.paragraphs).join(' ').length>1000);assert.equal(new Set(a.sections.map(s=>s.id)).size,a.sections.length)}});
test('search handles case and whitespace',()=>{assert.deepEqual(searchDocuments('  RUST  ',searchEntries),searchDocuments('rust',searchEntries));assert.ok(searchDocuments('rust',searchEntries).length>0)});
test('search matches body content and multi-term queries',()=>{assert.ok(searchDocuments('sibling prerequisites',searchEntries).some(e=>e.url.includes('getting-started')));assert.ok(searchDocuments('WAL',searchEntries).some(e=>e.url.includes('wdbx')))});
test('search has deterministic empty and no-result states',()=>{assert.equal(searchDocuments('',searchEntries).length,6);assert.deepEqual(searchDocuments('zxq_nonexistent_zz',searchEntries),[]);assert.deepEqual(searchDocuments('<script>alert(1)</script>',searchEntries),[])});
test('title match ranks above body match',()=>{const data=[{url:'/b/',title:'Other',description:'',body:'apple',group:'Test'},{url:'/a/',title:'Apple',description:'',body:'',group:'Test'}];assert.equal(searchDocuments('apple',data)[0].url,'/a/')});
test('project filters compose category and text without mutation',()=>{assert.equal(projects.filter(p=>matchProject('','all',p)).length,4);assert.deepEqual(projects.filter(p=>matchProject('rust','runtime',p)).map(p=>p.id),['abi']);assert.equal(projects.filter(p=>matchProject('rust','framework',p)).length,0)});
test('every source view renders a single primary heading',()=>{for(const route of siteRoutes){const html=render(View({route}));assert.equal((html.match(/<h1(?:\s|>)/g)||[]).length,1,route);assert.ok(routeTitle(route).includes('MLAI'))}});
test('unsafe strings are escaped by the review renderer',()=>assert.equal(render('<img src=x onerror=alert(1)>'),'&lt;img src=x onerror=alert(1)&gt;'));
test('unknown views render recovery navigation',()=>{const html=render(View({route:'/does-not-exist/'}));assert.match(html,/404/);assert.match(html,/Back to the beginning/)});
